('perawat', 19, 'TWK', 'Dalam kehidupan bernegara, hak dan kewajiban warga negara sebaiknya...', 'Dilaksanakan secara seimbang', 'Hanya hak yang diutamakan', 'Hanya kewajiban yang diutamakan', 'Diabaikan bila tidak menguntungkan', 'Ditentukan oleh kelompok tertentu saja', 'A'),
('perawat', 20, 'TWK', 'Sikap yang tepat ketika menerima informasi yang belum jelas kebenarannya adalah...', 'Langsung menyebarkannya', 'Memeriksa kebenaran melalui sumber tepercaya', 'Menambahkan informasi yang belum terbukti', 'Mengirimkannya ke semua grup', 'Menganggapnya pasti benar', 'B');
INSERT INTO questions (position, sort_order, section, question, option_a, option_b, option_c, option_d, option_e, answer_key) VALUES
('administrasi', 1, 'TWK', 'Toleransi dalam kehidupan antar umat beragama berarti…', 'Persebaran agama dapat dilakukan kepada siapa saja dan dimana saja', 'Setiap agama memiliki tujuan dan cara ibadah yang sama kepada Tuhan', 'Tersedianya tempat beribadah bagi semua umat beragama dan berdekatan', 'Setiap orang boleh berganti dan berpindah agama setiap saat, biladikehendaki', 'Menghargai aktivitas inter dan umat beragama serta pemerintah', 'E'),
('administrasi', 2, 'TWK', 'Cinta kepada tanah air dan bangsa dapat dibuktikan dengan cara…', 'Mengekspor semua hasil hasil bumi Indonesia dan mengimpor barang luar negeri', 'Tidak melakukan hubungan dengan negara lain dan melakukan proteksi', 'Menggunakan produksi dalam negeri meskipun mampu membelinya', 'Tidak menggunakan produksi luar negeri meskipun mampu membelinya', 'Mengurangi impor barang dari luar negeri agar devisa tetap stabil', 'E'),
('administrasi', 3, 'TWK', 'Seorang pemimpin seharusnya memberikan pekerjaan kepada bawahannya dengan bijaksana yaitu…', 'Selalu memberikan contoh pada setiap pekerjaan', 'Memberikan pekerjaan sesuai dengan kodrat kemanusiannya', 'Memilih dengan teliti pekerjaan yang pantas akan diberikan', 'Melakukan pengecekan langsung terhadap semua hasil bawahan', 'Menasehati setiap agar melakukan pekerjaan dengan baik', 'B'),
('administrasi', 4, 'TWK', 'Putusan yang diambil dalam musyawarah mufakat serta diliputi dengan semangat kekeluargaan adalah dengan…', 'Mengutamakan putusan golongan yang berkuasa', 'Melaksanakan hasil putusan bersama', 'Mempertahankan pendapat golongan yang sefaham', 'Meninggalkan ruang rapat karena berbeda pendapat', 'Menghormati pendapat yang disampaikan', 'B'),
('administrasi', 5, 'TWK', 'Sikap manusia yang bertakwa dapat dibuktikan dengan cara…', 'Selalu melindungi kesalahan orang lain', 'Bekerja siang dan malam agar berbahagia', 'Bersyukur dan selalu berusaha lebih baik', 'Hanya beribadah tanpa berusaha lebih baik', 'Kurang bersyukur terhadap hasil yang dicapai', 'C'),
('administrasi', 6, 'TWK', 'Proses penebangan hutan yang tidak mengindahkan keseimbangan antara alam dan manusianya akan berakibat…', 'Pengusaha semakin kaya dan korup', 'Meluaskan ozon di seluruh dunia', 'Kemiskinan bagi penduduk sekitar hutan', 'Reboisasi dan rehabilitasi hutan', 'Bencana alam yang tak terkendali', 'E'),
('administrasi', 7, 'TWK', 'Demokrasi adalah pemerintahan yang berasala dari rakyat, dilakukan oleh rakyat, dan untuk kepentingan rakyat sehingga kepentingan ada di tangan rakyat. Kedaulatan rakyat sepenuhnya dilakukan oleh…', 'DPR dan MPR', 'DPA dan BPK', 'Presiden', 'DPR', 'MPR', 'A'),
('administrasi', 8, 'TWK', 'Perilaku demokratis diharapkan tercipta dalam kehidupan bermasyarakat, berbangsa, dan bernegara seperti dewasa ini. Pengertian sikap demokratis secara sederhana adalah…', 'Mendengar dan menerima pendapat orang berdasarkan latar belakangnya', 'Menerima pendapat orang lain dengan tanpa pertimbangan', 'Mendesak orang lain agar menerima pendapat dan keinginannya', 'Menerima dan mengajukan pendapat dengan cara manusiawi', 'Memutuskan hasil rapat berdasarkan kepentingan pimpinan', 'D'),
('administrasi', 9, 'TWK', 'Seorang pemimpin harus berani mendorong orang-orang yang menjadi asuhannya, agar berani mengambil inisiatif dan sanggup mempertanggungjawabkannya. Pola kepemimpinan ini adalah…', 'Ing ngarsa sung tulada', 'Ing madya mangun karsa', 'Tut wuri handayani', 'Idealis dan karismatik', 'Demokratis dan populis', 'C'),
('administrasi', 10, 'TWK', 'Pada dasarnya UUD 1945 dapat diubah oleh MPR sesuai dengan pasal 37, dengan persyaratan…', 'Dihadiri oleh ½ jumlah anggota MPR dan semua anggota setuju', 'Disetujui oleh ½ jumlah anggota MPR dan dihadiri oleh 2/3 jumlah anggota MPR', 'Dihadiri oleh 2/3 jumlah anggota MPR dan disetujui oleh ½ yang hadir', 'Dihadiri dan disetujui oleh ½ jumlah anggota MPR lebih satu (1/2 + 1) jumlah anggota MPR', 'Dihadiri oleh 2/3jumlah anggota MPR dan disetujui oleh 2/3 jumlah anggota MPR yang hadir', 'C'),
('administrasi', 11, 'TWK', 'Rumusan Pancasila sebagai dasar negara untuk pertama kali dicetuskan dalam sidang......', 'PETA', 'BPUPKI', 'PPKI', 'Himpunan kebaktian rakyat jawa', 'Masyumi', 'B'),
