-- Pilih database di phpMyAdmin sebelum mengimpor. Backup bila database sudah berisi data.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS questions (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  position ENUM('perawat','administrasi','kebidanan','laboratorium','rekam_medis','radiografer') NOT NULL,
  sort_order SMALLINT UNSIGNED NOT NULL,
  section ENUM('TWK','SKD') NOT NULL DEFAULT 'SKD',
  question TEXT NOT NULL,
  option_a TEXT NOT NULL, option_b TEXT NOT NULL, option_c TEXT NOT NULL, option_d TEXT NOT NULL, option_e TEXT NOT NULL,
  answer_key ENUM('A','B','C','D','E') NOT NULL,
  UNIQUE KEY position_order (position, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS participants (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  email VARCHAR(254) NOT NULL,
  nik CHAR(16) NOT NULL,
  position ENUM('perawat','administrasi','kebidanan','laboratorium','rekam_medis','radiografer') NOT NULL,
  started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY unique_participant_nik (nik)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS submissions (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  submission_token CHAR(64) NOT NULL UNIQUE,
  participant_id BIGINT UNSIGNED NOT NULL UNIQUE,
  name VARCHAR(120) NOT NULL,
  email VARCHAR(254) NOT NULL,
  nik CHAR(16) NOT NULL,
  position ENUM('perawat','administrasi','kebidanan','laboratorium','rekam_medis','radiografer') NOT NULL,
  correct_count SMALLINT UNSIGNED NOT NULL,
  total_questions SMALLINT UNSIGNED NOT NULL,
  score DECIMAL(5,2) NOT NULL,
  submitted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (participant_id) REFERENCES participants(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS answers (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  submission_id BIGINT UNSIGNED NOT NULL,
  question_id INT UNSIGNED NULL,
  question_text TEXT NOT NULL,
  selected_option ENUM('A','B','C','D','E') NULL,
  selected_text TEXT NOT NULL,
  is_correct BOOLEAN NOT NULL,
  FOREIGN KEY (submission_id) REFERENCES submissions(id) ON DELETE CASCADE,
  FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE SET NULL,
  UNIQUE KEY submission_question (submission_id, question_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_login_attempts (
  ip_hash CHAR(64) PRIMARY KEY,
  attempts INT UNSIGNED NOT NULL DEFAULT 0,
  locked_until DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS draft_answers (
  participant_id BIGINT UNSIGNED NOT NULL,
  question_id INT UNSIGNED NOT NULL,
  selected_option ENUM('A','B','C','D','E') NOT NULL,
  PRIMARY KEY (participant_id, question_id),
  FOREIGN KEY (participant_id) REFERENCES participants(id) ON DELETE CASCADE,
  FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Gambar soal dikaitkan ke ID agar tidak bergantung pada posisi urutan soal.
CREATE TABLE IF NOT EXISTS question_images (
  question_id INT UNSIGNED PRIMARY KEY,
  image_name VARCHAR(255) NOT NULL,
  FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Menyesuaikan struktur dari versi paket 50 soal sebelumnya tanpa menghapus hasil.
ALTER TABLE questions MODIFY position ENUM('perawat','administrasi','kebidanan','laboratorium','rekam_medis','radiografer') NOT NULL;
ALTER TABLE participants MODIFY position ENUM('perawat','administrasi','kebidanan','laboratorium','rekam_medis','radiografer') NOT NULL;
ALTER TABLE submissions MODIFY position ENUM('perawat','administrasi','kebidanan','laboratorium','rekam_medis','radiografer') NOT NULL;
ALTER TABLE answers MODIFY selected_option ENUM('A','B','C','D','E') NULL;

-- Contoh administrasi lama perlu diganti, tetapi soal yang sudah disunting dipertahankan.
SET @legacy_administration = (SELECT COUNT(*) FROM questions WHERE position='administrasi' AND sort_order=1 AND question='Saat menerima telepon dari pihak luar, tindakan pertama yang tepat adalah...');

-- Soal SKD keperawatan ditranskripsikan dari SOAL KEPERAWATAN.docx.

-- CONTOH SEMENTARA, bukan soal dari mentor. Validasi dan ganti sebelum digunakan.

-- 20 TWK dari SOAL KEBIDANAN 2.docx; 30 SKD per bidang dari dokumen masing-masing.
-- Kunci ditranskripsikan dari teks tebal/sorotan/kunci dokumen; harus divalidasi mentor.
ON DUPLICATE KEY UPDATE section=IF(@legacy_administration = 1 AND position = 'administrasi', VALUES(section), section), question=IF(@legacy_administration = 1 AND position = 'administrasi', VALUES(question), question), option_a=IF(@legacy_administration = 1 AND position = 'administrasi', VALUES(option_a), option_a), option_b=IF(@legacy_administration = 1 AND position = 'administrasi', VALUES(option_b), option_b), option_c=IF(@legacy_administration = 1 AND position = 'administrasi', VALUES(option_c), option_c), option_d=IF(@legacy_administration = 1 AND position = 'administrasi', VALUES(option_d), option_d), option_e=IF(@legacy_administration = 1 AND position = 'administrasi', VALUES(option_e), option_e), answer_key=IF(@legacy_administration = 1 AND position = 'administrasi', VALUES(answer_key), answer_key);


-- Rekam medis: TWK sama dengan laboratorium; SKD dan kunci dari Soal Rekam Medis.docx.
-- INSERT IGNORE menjaga soal rekam medis yang sudah disunting pada impor ulang.

-- Radiografer: kunci SKD sementara hasil referensi, wajib validasi mentor.
-- INSERT IGNORE mempertahankan perubahan panitia saat impor ulang.

-- Hanya tautkan gambar jika isi soal asli belum diubah.
SELECT id, 'soal-radiografer-siku.jpg' FROM questions WHERE position = 'radiografer' AND sort_order = 30 AND question = 'Pada gambar radiografi elbow joint proyeksi AP pada seorang pasien didapatkan gambaran seperti pada gambar berikut. Apa nama tulang yang ditunjukkan tanda panah tersebut?';
